            if !validDirectives[part] || len(infoContent) > 256 {
                return header
            }
        }
    default:
        // Invalid infoType
        return header
    }

    if header == nil {
        return header
    }

    // Check if content is empty after validation
    if infoContent == "" {
        return header
    }

    header[key] = infoContent

    return header
