    size_t domain_len = strlen(domain);
    size_t subdomain_len = strlen(subdomain_prefix);
    // Maximum URL format: "https://subdomain.domain" or "https://domain"
    size_t total_length = 8 + subdomain_len + domain_len + (subdomain_len > 0 ? 1 : 0); // "+1 for the dot if subdomain is present"
    if (total_length > MAX_URL_LENGTH) {
        return NULL;
    }
    // Allocate memory
    char* url = malloc(total_length);
    if (url == NULL) {
        return NULL;
    }
    // Construct URL
    if (subdomain_len > 0) {
        snprintf(url, total_length, "https://%s.%s", subdomain_prefix, domain);
    } else {
